package com.globalhire.controller;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestTemplate;import java.util.*;@RestController @RequestMapping("/api/ml")public class MLController{final RestTemplate http=new RestTemplate();@Value("${app.ml-url}")String url;Map<String,Object> post(String path,Map<String,Object>b){return http.postForObject(url+"/api/ml/"+path,b,Map.class);}@PostMapping("/offer-acceptance")Map<String,Object> offer(@RequestBody Map<String,Object>b){return post("offer-acceptance",b);}@PostMapping("/hiring-cost")Map<String,Object> cost(@RequestBody Map<String,Object>b){return post("hiring-cost",b);}@PostMapping("/time-to-hire")Map<String,Object> time(@RequestBody Map<String,Object>b){return post("time-to-hire",b);}@PostMapping("/retention")Map<String,Object> retention(@RequestBody Map<String,Object>b){return post("retention",b);}@PostMapping("/compliance")Map<String,Object> compliance(@RequestBody Map<String,Object>b){return post("compliance",b);}}